from __future__ import annotations

import asyncio
import inspect
import time
from collections.abc import Awaitable, Callable
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from typing import TypeAlias

from freesolo.datasets import TaskExample
from freesolo.datasets.records import load_task_examples
from freesolo.datasets.types import DatasetSource

from ..contracts.markdown import ChatMessage, load_contract_text
from ..evaluation.results import ScorerData, ScorerMetricData, ScoringResult
from ..utils.core import JsonObject, json_safe_value
from .base import (
    Environment,
    EnvironmentMultiTurn,
    _validate_environment,
    load_environment,
)
from .types import (
    EnvironmentEpisode,
    EnvironmentGeneration,
    EnvironmentMetadata,
    EnvironmentStepResult,
    EnvironmentTurn,
    GenerationValue,
    RewardMetric,
    RewardResult,
)

EnvironmentGenerate: TypeAlias = Callable[
    [list[ChatMessage], TaskExample],
    GenerationValue | Awaitable[GenerationValue],
]
EnvironmentSource: TypeAlias = DatasetSource


def _run_local_environment_evaluation(
    *,
    source: EnvironmentSource,
    generate: EnvironmentGenerate,
    contract_path: str | Path = "TRAINING_CONTRACT.md",
    contract_text: str | None = None,
    environment: str | Environment | None = None,
    environment_kwargs: dict[str, object] | None = None,
    concurrency: int = 1,
) -> list[ScoringResult]:
    """Run an environment end-to-end and return DB-compatible eval results.

    Flow:
    load examples -> build prompt messages -> call generate -> score response.
    Internal implementation for EvaluationClient.run_environment.
    """

    resolved_contract_text = (
        contract_text
        if contract_text is not None
        else load_contract_text(contract_path)
    )
    resolved_environment = _resolve_environment(
        environment,
        source=source,
        contract_path=contract_path,
        environment_kwargs=environment_kwargs,
    )
    examples = load_task_examples(source)
    started = time.monotonic()
    worker_count = _resolve_concurrency(concurrency)
    if worker_count == 1:
        results = [
            _evaluate_example(
                example,
                environment=resolved_environment,
                generate=generate,
                contract_text=resolved_contract_text,
            )
            for example in examples
        ]
    else:
        results_by_index: list[ScoringResult | None] = [None] * len(examples)
        with ThreadPoolExecutor(max_workers=worker_count) as executor:
            futures = {
                executor.submit(
                    _evaluate_example,
                    example,
                    environment=resolved_environment,
                    generate=generate,
                    contract_text=resolved_contract_text,
                ): index
                for index, example in enumerate(examples)
            }
            for future in as_completed(futures):
                results_by_index[futures[future]] = future.result()
        results = [result for result in results_by_index if result is not None]

    run_duration = time.monotonic() - started
    for result in results:
        result.run_duration = run_duration
    return results


def _evaluate_example(
    example: TaskExample,
    *,
    environment: Environment,
    generate: EnvironmentGenerate,
    contract_text: str,
) -> ScoringResult:
    episode = _run_environment_episode(
        example,
        environment=environment,
        generate=generate,
        contract_text=contract_text,
    )
    reward_results = environment.score_episodes(example, [episode])
    if len(reward_results) != 1:
        raise RuntimeError(
            "Environment score_episodes() must return one RewardResult per "
            "generated episode"
        )

    scorer = _reward_to_scorer_data(
        reward_results[0],
        latency_ms=episode.latency_ms,
        total_tokens=episode.total_tokens,
    )
    data_object = _data_object(example, episode=episode, environment=environment)
    return ScoringResult(
        success=scorer.success,
        scorers_data=[scorer],
        data_object=data_object,
    )


def _run_environment_episode(
    example: TaskExample,
    *,
    environment: Environment,
    generate: EnvironmentGenerate,
    contract_text: str,
) -> EnvironmentEpisode:
    messages = list(environment.start_episode(example, contract_text))
    turns: list[EnvironmentTurn] = []
    episode_metadata: EnvironmentMetadata = {}
    total_latency_ms = 0
    total_tokens: int | None = None
    final_response_text = ""

    max_turns = _resolve_max_episode_turns(environment.max_episode_turns(example))
    for turn_index in range(max_turns):
        generation_started = time.monotonic()
        generation = _resolve_generation(
            _call_generate(
                generate,
                messages=list(messages),
                example=example,
                environment=environment,
                contract_text=contract_text,
                turn_index=turn_index,
                turns=tuple(turns),
            )
        )
        measured_latency_ms = int((time.monotonic() - generation_started) * 1000)
        latency_ms = generation.latency_ms
        if latency_ms is None:
            latency_ms = measured_latency_ms
        total_latency_ms += latency_ms
        if generation.total_tokens is not None:
            total_tokens = (total_tokens or 0) + generation.total_tokens
        if generation.metadata and max_turns == 1 and not episode_metadata:
            episode_metadata.update(generation.metadata)
        elif generation.metadata:
            episode_metadata.setdefault("generations", [])
            generations = episode_metadata["generations"]
            if isinstance(generations, list):
                generations.append(generation.metadata)

        response_text = environment.normalize_response_text(
            example,
            generation.response_text,
        )
        final_response_text = response_text
        assistant_message: ChatMessage = {"role": "assistant", "content": response_text}
        messages.append(assistant_message)
        turns.append(
            EnvironmentTurn(
                role="assistant",
                content=response_text,
                metadata=generation.metadata,
            )
        )

        step = environment.step_episode(example, messages, response_text)
        _merge_episode_metadata(episode_metadata, step)
        for message in step.messages:
            messages.append(message)
            turns.append(
                EnvironmentTurn(
                    role=message["role"],
                    content=message["content"],
                )
            )
        if step.done:
            if step.final_response_text is not None:
                final_response_text = step.final_response_text
            break

    return EnvironmentEpisode(
        messages=tuple(messages),
        response_text=final_response_text,
        turns=tuple(turns),
        metadata=episode_metadata,
        latency_ms=total_latency_ms,
        total_tokens=total_tokens,
    )


def _resolve_concurrency(value: int) -> int:
    if isinstance(value, bool) or value < 1:
        raise ValueError("concurrency must be a positive integer")
    return value


def _resolve_max_episode_turns(value: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        raise ValueError("max_episode_turns must be a positive integer")
    return value


def _merge_episode_metadata(
    episode_metadata: EnvironmentMetadata,
    step: EnvironmentStepResult,
) -> None:
    if not step.metadata:
        return
    episode_metadata.setdefault("steps", [])
    steps = episode_metadata["steps"]
    if isinstance(steps, list):
        steps.append(step.metadata)


def _resolve_environment(
    environment: str | Environment | None,
    *,
    source: EnvironmentSource,
    contract_path: str | Path,
    environment_kwargs: dict[str, object] | None,
) -> Environment:
    if isinstance(environment, Environment):
        return _validate_environment(environment)

    kwargs = dict(environment_kwargs or {})
    kwargs.setdefault("contract_path", str(contract_path))
    kwargs.setdefault("mode", "eval")
    if isinstance(source, (str, Path)):
        kwargs.setdefault("dataset_path", str(source))
    return load_environment(environment, **kwargs)


def _call_generate(
    generate: EnvironmentGenerate,
    *,
    messages: list[ChatMessage],
    example: TaskExample,
    environment: Environment,
    contract_text: str,
    turn_index: int = 0,
    turns: tuple[EnvironmentTurn, ...] = (),
) -> GenerationValue | Awaitable[GenerationValue]:
    try:
        signature = inspect.signature(generate)
    except (TypeError, ValueError):
        return generate(messages, example)
    parameters = list(signature.parameters.values())
    accepts_kwargs = any(
        parameter.kind == inspect.Parameter.VAR_KEYWORD for parameter in parameters
    )
    named_arguments: dict[str, object] = {
        "messages": messages,
        "example": example,
        "environment": environment,
        "contract_text": contract_text,
        "turn_index": turn_index,
        "turns": turns,
    }
    if accepts_kwargs:
        return generate(**named_arguments)  # type: ignore[call-arg, misc]

    keyword_arguments = {
        name: value
        for name, value in named_arguments.items()
        if name in signature.parameters
    }
    if keyword_arguments:
        return generate(**keyword_arguments)  # type: ignore[call-arg, misc]

    positional_parameters = [
        parameter
        for parameter in parameters
        if parameter.kind
        in {
            inspect.Parameter.POSITIONAL_ONLY,
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
        }
    ]
    if len(positional_parameters) <= 1:
        return generate(messages)  # type: ignore[call-arg]
    return generate(messages, example)


async def _resolve_awaitable(value: Awaitable[GenerationValue]) -> GenerationValue:
    return await value


def _resolve_generation(
    value: GenerationValue | Awaitable[GenerationValue],
) -> EnvironmentGeneration:
    if inspect.isawaitable(value):
        value = asyncio.run(_resolve_awaitable(value))
    if isinstance(value, EnvironmentGeneration):
        return value
    if isinstance(value, str):
        return EnvironmentGeneration(response_text=value)
    raise TypeError(
        "Environment generate() must return str or EnvironmentGeneration, "
        f"got {type(value).__name__}"
    )


def _reward_to_scorer_data(
    reward: RewardResult,
    *,
    latency_ms: int | None,
    total_tokens: int | None,
) -> ScorerData:
    return ScorerData(
        name=reward.name or "environment_reward",
        success=reward.resolved_success(),
        value=reward.resolved_value(),
        score=reward.score,
        threshold=reward.threshold,
        reason=reward.reason,
        error=reward.error,
        return_type=reward.return_type,
        latency_ms=reward.latency_ms if reward.latency_ms is not None else latency_ms,
        total_tokens=reward.total_tokens
        if reward.total_tokens is not None
        else total_tokens,
        metadata=reward.metadata,
        metrics=[_metric_to_scorer_metric(metric) for metric in reward.metrics],
    )


def _metric_to_scorer_metric(metric: RewardMetric) -> ScorerMetricData:
    return ScorerMetricData(
        name=metric.name,
        score=metric.score,
        value=metric.value,
        success=metric.success,
        threshold=metric.threshold,
        weight=metric.weight,
        reason=metric.reason,
        metadata=metric.metadata,
    )


def _data_object(
    example: TaskExample,
    *,
    episode: EnvironmentEpisode,
    environment: Environment,
) -> JsonObject:
    payload: JsonObject = {
        "input": example.input,
        "actual_output": episode.response_text,
    }
    if example.output is not None:
        payload["output"] = json_safe_value(example.output)
    if example.id:
        payload["id"] = example.id
    if example.metadata:
        payload["metadata"] = example.metadata
    if episode.metadata:
        payload["generation_metadata"] = episode.metadata
    if isinstance(environment, EnvironmentMultiTurn):
        payload["turns"] = [turn.to_dict() for turn in episode.turns]
        payload["messages"] = [
            {"role": message["role"], "content": message["content"]}
            for message in episode.messages
        ]
    image_url = example.record.get("image_url")
    if isinstance(image_url, str):
        payload["image_url"] = image_url
    return payload


__all__ = [
    "EnvironmentGeneration",
]
